// === Tab: mySketch.js ===
p5.disableFriendlyErrors = true;
const SPEED = 0.4;
const FPS_COUNTER = false;
const f = 6;
const b = 6;
const samples = 1;
const gaussian = 0.2;
const multipler = 0.4;
const baseWeight = 0.22;

let curv = -0.03;
let dir = 1.0;
let distribution;
let weightoffset;
let sed;
let fc = 0;

const PI = Math.PI;
const HALF_PI = Math.PI / 2;
const cos = Math.cos;
const sin = Math.sin;
const pow = Math.pow;
const sqrt = Math.sqrt;
const atan2 = Math.atan2;

const MAX_STACK_SIZE = 10000; 
const STACK_STRIDE = 6; 
let stackData; 
let powCache = new Float32Array(b);

// ---- FPS SMOOTH ----
let smoothFPS = 0;
const fpsLerp = 0.07;
// --------------------

function setup() {
	frameRate(60);
	pixelDensity(1);
	sed = random() * 999999999;
	noiseDetail(2, 0.5);
	createCanvas(windowWidth, windowHeight);
	noFill();
	colorMode(RGB, 1);
	strokeCap(SQUARE);
	stackData = new Float64Array(MAX_STACK_SIZE * STACK_STRIDE);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function fractalIterative(startX, startY, startLx, startLy, startLayer, branch, startMutation, size) {

	let sp = 0; 

	stackData[sp++] = startX;
	stackData[sp++] = startY;
	stackData[sp++] = startLx;
	stackData[sp++] = startLy;
	stackData[sp++] = startLayer;
	stackData[sp++] = startMutation;

	const ctx = drawingContext;

	for (let i = 0; i < branch; i++) {
		powCache[i] = pow((i + 1) / branch, distribution);
	}

	const g = baseWeight;
	const widthPlusHeightDiv1000 = (width + height) / 1000;

	while (sp > 0) {

		let mutation = stackData[--sp];
		let layer = stackData[--sp];
		let ly = stackData[--sp];
		let lx = stackData[--sp];
		let y = stackData[--sp];
		let x = stackData[--sp];

		let lenMag = sqrt(lx * lx + ly * ly) * size;
		let x2 = x + lx;
		let y2 = y + ly;

		let alpha = (baseWeight * layer) / f + baseWeight;
		let noiseComp = noise(mutation); 
		let sw = widthPlusHeightDiv1000 * ((layer + weightoffset) + noiseComp);

		if (sw > 0.1) {
			ctx.lineWidth = sw * 0.7;
			ctx.strokeStyle = `rgba(0, ${Math.floor(g*255)}, 0, ${alpha})`;
			ctx.beginPath();
			ctx.moveTo(x, y);
			ctx.lineTo(x2, y2);
			ctx.stroke();
		}

		if (layer > 1) {
			let noiseVal = noise(mutation, fc / 123) * 0.3;
			let currentAngle = atan2(ly, lx);

			for (let i = branch - 1; i >= 0; i--) {

				let t = powCache[i];
				let newX = x + lx * t;
				let newY = y + ly * t;
				let newLenMag = lenMag * (multipler + noiseVal);

				let angleOffset = (i * PI + HALF_PI);
				angleOffset += (((((i+1)%2)*2)-1) * (curv - dir));
				angleOffset += (random() - 0.5 + random() - 0.5) * gaussian; 

				let totalAngle = currentAngle + angleOffset;
				let newLx = cos(totalAngle) * newLenMag;
				let newLy = sin(totalAngle) * newLenMag;
				let newMutation = mutation + random() * 2000;

				stackData[sp++] = newX;
				stackData[sp++] = newY;
				stackData[sp++] = newLx;
				stackData[sp++] = newLy;
				stackData[sp++] = layer - 1;
				stackData[sp++] = newMutation;
			}
		}
	}
}

function draw() {

	randomSeed(sed);
	var ctx = drawingContext;

	ctx.fillStyle = "rgba(230, 230, 230, 0.58)";
	ctx.fillRect(0, 0, width, height);

	// ---- SMOOTH FPS ----
	if(FPS_COUNTER) {
		let currentFPS = 1000 / deltaTime;
		smoothFPS += (currentFPS - smoothFPS) * fpsLerp;

		fill(0.9);
		noStroke();
		rect(0, 0, 60, 30);
		fill(0);
		text(smoothFPS.toFixed(1), 10, 20);		
	}
	// ---------------------

	for(let i = 0; i < samples; i++) {

		fc = frameCount * SPEED + i*1000000;
		distribution = pow(5, 2 * noise(fc / 552) - 1);
		weightoffset = noise(fc / 2745) * 4 - 1;
		curv = noise(234 - fc / 783) * 2;
		dir = -PI - HALF_PI * pow(noise(0, fc / 323 + 1000), 1/2)*1.6;
		let size = pow(noise(34234 - (fc / 383)), 1/3)*0.6 + 0.6;
		push();
		translate(width / 2, height / 2);
		rotate(PI);
		translate(-width / 2, -height / 2);
		scale(0.3);
		translate(width * 0.5, height * 0.4);

		fractalIterative(
			width/samples*(((i)*3)-((samples-3)/3)),
			height*0.4,
			width/(samples+1),
			height*0.8,
			f,
			b,
			0,
			size
		);

		pop();
	}
}


